        "Fast / Auto / Expert / Heavy map onto local models and effort.": [
            "ja": "Fast / Auto / Expert / Heavy はローカルのモデルと推論強度に対応します。",
            "ko": "Fast / Auto / Expert / Heavy 는 로컬 모델과 추론 강도에 대응합니다.",
            "de": "Fast / Auto / Expert / Heavy werden auf lokale Modelle und die Inferenzstärke abgebildet.",
            "fr": "Fast / Auto / Expert / Heavy correspondent aux modèles locaux et à l’intensité de raisonnement.",
            "ru": "Fast / Auto / Expert / Heavy сопоставляются с локальными моделями и силой рассуждения.",
            "es": "Fast / Auto / Expert / Heavy se asignan a modelos locales y a la intensidad de razonamiento.",
            "pt-BR": "Fast / Auto / Expert / Heavy mapeiam para modelos locais e a intensidade de raciocínio.",
            "it": "Fast / Auto / Expert / Heavy corrispondono ai modelli locali e all’intensità di ragionamento.",
            "id": "Fast / Auto / Expert / Heavy dipetakan ke model lokal dan kekuatan penalaran.",
            "ta": "Fast / Auto / Expert / Heavy உள்ளூர் மாதிரிகளுக்கும் பகுத்தறிவு வலிமைக்கும் பொருந்தும்.",
            "uk": "Fast / Auto / Expert / Heavy зіставляються з локальними моделями та силою міркування.",
            "fil": "Ang Fast / Auto / Expert / Heavy ay naka-map sa mga lokal na model at lakas ng pangangatwiran.",
            "tr": "Fast / Auto / Expert / Heavy yerel modellere ve akıl yürütme yoğunluğuna eşlenir.",
        ],
        "Send feedback through the local grok CLI.": [
            "ja": "フィードバックはローカルの grok CLI から送ります。",
            "ko": "피드백은 로컬 grok CLI로 보냅니다.",
            "de": "Feedback über die lokale grok CLI senden.",
            "fr": "Envoyer le retour via la grok CLI locale.",
            "ru": "Отправлять отзыв через локальную grok CLI.",
            "es": "Enviar comentarios mediante la grok CLI local.",
            "pt-BR": "Enviar feedback pela grok CLI local.",
            "it": "Invia feedback tramite la grok CLI locale.",
            "id": "Kirim masukan lewat grok CLI lokal.",
            "ta": "கருத்தை உள்ளூர் grok CLI வழியாக அனுப்பவும்.",
            "uk": "Надсилати відгук через локальну grok CLI.",
            "fil": "Magpadala ng feedback sa lokal na grok CLI.",
            "tr": "Geri bildirimi yerel grok CLI ile gönderin.",
        ],
        "Billing stays on grok.com / `/usage`.": [
            "ja": "請求は grok.com または `/usage` で管理します。",
            "ko": "요금은 grok.com 또는 `/usage`에서 관리합니다.",
            "de": "Die Abrechnung bleibt auf grok.com oder in `/usage`.",
            "fr": "La facturation reste sur grok.com ou dans `/usage`.",
            "ru": "Оплата остаётся на grok.com или в `/usage`.",
            "es": "La facturación sigue en grok.com o en `/usage`.",
            "pt-BR": "A cobrança continua em grok.com ou em `/usage`.",
            "it": "La fatturazione resta su grok.com o in `/usage`.",
            "id": "Tagihan tetap di grok.com atau `/usage`.",
            "ta": "கட்டணம் grok.com அல்லது `/usage` இல் இருக்கும்.",
