        "Training and retention follow your grok.com / `/privacy` choice. This app only talks to the local grok CLI.": [
            "ja": "学習と保持は grok.com または `/privacy` の選択に従います。このアプリはローカルの grok CLI とだけ通信します。",
            "ko": "학습과 보관은 grok.com 또는 `/privacy` 선택을 따릅니다. 이 앱은 로컬 grok CLI와만 통신합니다.",
            "de": "Training und Aufbewahrung folgen Ihrer Wahl auf grok.com oder in `/privacy`. Diese App spricht nur mit der lokalen grok CLI.",
            "fr": "L’entraînement et la conservation suivent votre choix sur grok.com ou dans `/privacy`. Cette app ne parle qu’à la grok CLI locale.",
            "ru": "Обучение и хранение следуют вашему выбору на grok.com или в `/privacy`. Это приложение общается только с локальной grok CLI.",
            "es": "El entrenamiento y la retención siguen tu elección en grok.com o en `/privacy`. Esta app solo habla con la grok CLI local.",
            "pt-BR": "O treinamento e a retenção seguem sua escolha em grok.com ou em `/privacy`. Este app só fala com a grok CLI local.",
            "it": "Addestramento e conservazione seguono la scelta su grok.com o in `/privacy`. Questa app parla solo con la grok CLI locale.",
            "id": "Pelatihan dan retensi mengikuti pilihan Anda di grok.com atau `/privacy`. Aplikasi ini hanya berbicara dengan grok CLI lokal.",
            "ta": "பயிற்சியும் தக்கவைப்பும் grok.com அல்லது `/privacy` தேர்வைப் பின்பற்றும். இந்தச் செயலி உள்ளூர் grok CLI உடன் மட்டுமே பேசும்.",
            "uk": "Навчання й зберігання відповідають вашому вибору на grok.com або в `/privacy`. Цей застосунок говорить лише з локальною grok CLI.",
            "fil": "Ang training at retention ay sumusunod sa pinili mo sa grok.com o `/privacy`. Ang app na ito ay kausap lang ang lokal na grok CLI.",
            "tr": "Eğitim ve saklama, grok.com veya `/privacy` seçiminize uyar. Bu uygulama yalnızca yerel grok CLI ile konuşur.",
        ],
        "Auto-compact threshold": [
