        "Add MCP": [
            "ja": "MCP を追加",
            "ko": "MCP 추가",
            "de": "MCP hinzufügen",
            "fr": "Ajouter un MCP",
            "ru": "Добавить MCP",
            "es": "Añadir MCP",
            "pt-BR": "Adicionar MCP",
            "it": "Aggiungi MCP",
            "id": "Tambah MCP",
            "ta": "MCP சேர்",
            "uk": "Додати MCP",
            "fil": "Magdagdag ng MCP",
            "tr": "MCP ekle",
        ],
        "Grok-native servers can be added here. Inherited Claude/plugin connectors are listed but edited at their source.": [
            "ja": "ここでは Grok 独自の MCP を追加・削除できます。Claude やプラグインから継承したコネクタは一覧のみで、編集は元の場所で行います。",
            "ko": "여기서는 Grok 자체 MCP를 추가하거나 삭제할 수 있습니다. Claude나 플러그인에서 상속된 커넥터는 목록에만 나오며, 원래 자리에서 편집합니다.",
            "de": "Hier können Sie eigene MCP von Grok hinzufügen oder entfernen. Geerbte Konnektoren von Claude oder Plugins werden nur aufgelistet und an der Quelle bearbeitet.",
            "fr": "Ici, vous pouvez ajouter ou retirer les MCP propres à Grok. Les connecteurs hérités de Claude ou d’un plug-in sont listés, mais se modifient à la source.",
            "ru": "Здесь можно добавлять и удалять собственные MCP Grok. Унаследованные коннекторы Claude и плагинов только перечислены; правьте их в источнике.",
            "es": "Aquí puedes añadir o quitar los MCP propios de Grok. Los conectores heredados de Claude o de un plugin solo se listan; se editan en su origen.",
            "pt-BR": "Aqui você pode adicionar ou remover os MCP do próprio Grok. Conectores herdados do Claude ou de plugins só são listados; edite-os na origem.",
            "it": "Qui puoi aggiungere o rimuovere gli MCP nativi di Grok. I connettori ereditati da Claude o dai plugin sono solo elencati; si modificano all’origine.",
            "id": "Di sini Anda dapat menambah atau menghapus MCP milik Grok. Konektor warisan Claude atau plugin hanya ditampilkan; edit di sumbernya.",
            "ta": "இங்கே Grok இன் சொந்த MCP ஐச் சேர்க்கவோ நீக்கவோ முடியும். Claude அல்லது செருகுநிரலில் இருந்து வந்த இணைப்பான்கள் பட்டியலில் மட்டுமே; மூலத்திலேயே திருத்தவும்.",
            "uk": "Тут можна додавати й видаляти власні MCP Grok. Успадковані конектори Claude чи плагінів лише перелічені; редагуйте їх у джерелі.",
            "fil": "Dito maaari kang magdagdag o mag-alis ng sariling MCP ng Grok. Ang mga minanang connector ng Claude o plugin ay nakalista lang; i-edit sa pinagmulan.",
            "tr": "Burada Grok’a ait MCP eklenebilir veya kaldırılabilir. Claude veya eklentiden devralınan bağlayıcılar yalnızca listelenir; kaynağında düzenlenir.",
        ],
