        "\\(version) is downloaded. It installs the next time you open the app.": [
            "ja": "\\(version) をダウンロードしました。次回起動時にインストールされます。",
            "ko": "\\(version)을 받았습니다. 다음에 앱을 열 때 설치됩니다.",
            "de": "\\(version) wurde geladen. Die Installation erfolgt beim nächsten Öffnen der App.",
            "fr": "\\(version) est téléchargée. Elle s’installera à la prochaine ouverture de l’app.",
            "ru": "\\(version) загружена. Она установится при следующем открытии приложения.",
            "es": "\\(version) se ha descargado. Se instalará la próxima vez que abras la app.",
            "pt-BR": "\\(version) foi baixada. Será instalada na próxima vez que você abrir o app.",
            "it": "\\(version) è stata scaricata. Si installerà alla prossima apertura dell’app.",
            "id": "\\(version) sudah diunduh. Terpasang saat Anda membuka aplikasi lagi.",
            "ta": "\\(version) பதிவிறக்கப்பட்டது. அடுத்த முறை செயலியைத் திறக்கும்போது நிறுவப்படும்.",
            "uk": "\\(version) завантажено. Встановиться під час наступного відкриття програми.",
            "fil": "Na-download na ang \\(version). Mai-install ito sa susunod na buksan mo ang app.",
            "tr": "\\(version) indirildi. Uygulamayı bir sonraki açışınızda yüklenir.",
        ],
        "Move Grok Desktop into the Applications folder to install updates.": [
            "ja": "更新を入れるには、Grok Desktop をアプリケーションフォルダへ移動してください。",
            "ko": "업데이트를 설치하려면 Grok Desktop을 응용 프로그램 폴더로 옮기세요.",
            "de": "Verschieben Sie Grok Desktop in den Ordner „Programme“, um Updates zu installieren.",
            "fr": "Déplacez Grok Desktop dans le dossier Applications pour installer les mises à jour.",
            "ru": "Переместите Grok Desktop в папку «Программы», чтобы устанавливать обновления.",
            "es": "Mueve Grok Desktop a la carpeta Aplicaciones para instalar actualizaciones.",
            "pt-BR": "Mova o Grok Desktop para a pasta Aplicativos para instalar atualizações.",
            "it": "Sposta Grok Desktop nella cartella Applicazioni per installare gli aggiornamenti.",
            "id": "Pindahkan Grok Desktop ke folder Aplikasi agar pembaruan bisa dipasang.",
            "ta": "புதுப்பிப்புகளை நிறுவ Grok Desktop ஐப் பயன்பாடுகள் கோப்புறைக்கு நகர்த்தவும்.",
            "uk": "Перемістіть Grok Desktop до папки «Програми», щоб встановлювати оновлення.",
            "fil": "Ilipat ang Grok Desktop sa folder na Applications para makapag-install ng update.",
            "tr": "Güncellemeleri yüklemek için Grok Desktop’ı Uygulamalar klasörüne taşıyın.",
        ],
        "This app is up to date.": [
            "ja": "このアプリは最新です。",
            "ko": "이 앱은 최신 상태입니다.",
            "de": "Diese App ist auf dem neuesten Stand.",
            "fr": "Cette app est à jour.",
            "ru": "Это приложение уже последней версии.",
            "es": "Esta app está actualizada.",
            "pt-BR": "Este app está atualizado.",
            "it": "Questa app è aggiornata.",
            "id": "Aplikasi ini sudah yang terbaru.",
