            "ko": "실행할 때와 이후 \\(hours)시간마다 확인합니다. 더 새로운 버전은 저절로 받아집니다.",
            "de": "Prüfung beim Start und dann alle \\(hours) Stunden. Eine neuere Version lädt sich von selbst herunter.",
            "fr": "Vérification au lancement, puis toutes les \\(hours) heures. Une version plus récente se télécharge seule.",
            "ru": "Проверка при запуске и далее каждые \\(hours) ч. Более новая версия скачивается сама.",
            "es": "Comprueba al abrir y luego cada \\(hours) horas. Una versión más nueva se descarga sola.",
            "pt-BR": "Verifica ao abrir e depois a cada \\(hours) horas. Uma versão mais nova baixa sozinha.",
            "it": "Controlla all’avvio e poi ogni \\(hours) ore. Una versione più recente si scarica da sola.",
            "id": "Memeriksa saat dibuka, lalu setiap \\(hours) jam. Versi yang lebih baru mengunduh sendiri.",
            "ta": "தொடக்கத்திலும், பின்னர் ஒவ்வொரு \\(hours) மணிநேரமும் பார்க்கும். புதிய பதிப்பு தானாக இறங்கும்.",
            "uk": "Перевірка під час запуску і далі кожні \\(hours) год. Новіша версія завантажується сама.",
            "fil": "Tinitingnan sa pagbukas at tuwing \\(hours) oras. Ang mas bagong bersyon ay nagda-download nang kusa.",
            "tr": "Açılışta ve sonra her \\(hours) saatte bir denetler. Daha yeni sürüm kendiliğinden iner.",
