            "ta": "வரும் உரை, நம்பிய திட்டத்தில் மட்டும் Build சுற்றைத் தொடங்கும். /p திட்டத்தைத் தேர்ந்தெடுக்கும், /r ஏற்கெனவே உள்ள அமர்வைத் தொடரும்.",
