        "When enabled, press Cmd+Enter (or Ctrl+Enter) to submit. Enter will add a new line.": [
            "ja": "有効にすると、Cmd+Enter（または Ctrl+Enter）で送信します。Enter は改行です。",
            "ko": "켜면 Cmd+Enter(또는 Ctrl+Enter)로 보냅니다. Enter는 줄 바꿈입니다.",
            "de": "Wenn aktiv, sende mit Cmd+Enter (oder Ctrl+Enter). Enter fügt eine neue Zeile ein.",
            "fr": "Si activé, appuyez sur Cmd+Enter (ou Ctrl+Enter) pour envoyer. Enter ajoute une ligne.",
            "ru": "Если включено, отправляйте через Cmd+Enter (или Ctrl+Enter). Enter переносит строку.",
            "es": "Si está activado, pulsa Cmd+Enter (o Ctrl+Enter) para enviar. Enter añade una línea.",
            "pt-BR": "Quando ativado, pressione Cmd+Enter (ou Ctrl+Enter) para enviar. Enter adiciona uma linha.",
            "it": "Se attivo, premi Cmd+Enter (o Ctrl+Enter) per inviare. Enter aggiunge una riga.",
            "id": "Jika aktif, tekan Cmd+Enter (atau Ctrl+Enter) untuk mengirim. Enter menambah baris.",
            "ta": "இயக்கினால், அனுப்ப Cmd+Enter (அல்லது Ctrl+Enter) அழுத்துங்கள். Enter புதிய வரியைச் சேர்க்கும்.",
            "uk": "Якщо ввімкнено, надсилайте через Cmd+Enter (або Ctrl+Enter). Enter переносить рядок.",
            "fil": "Kapag naka-on, pindutin ang Cmd+Enter (o Ctrl+Enter) para magpadala. Nagdadagdag ng linya ang Enter.",
            "tr": "Açıksa göndermek için Cmd+Enter (veya Ctrl+Enter) kullanın. Enter yeni satır ekler.",
