        "Send now cancels the current turn and runs this next. Edit keeps the text. Cancel drops it.": [
            "ja": "今すぐ送信すると現在のターンを取り消してこれをすぐ送ります。編集は入力欄に戻します。キャンセルは破棄します。",
            "ko": "지금 보내면 현재 턴이 취소되고 이 내용이 바로 전송됩니다. 편집은 입력창으로 되돌립니다. 취소는 버립니다.",
            "de": "Jetzt senden bricht den aktuellen Zug ab und sendet dies sofort. Bearbeiten legt den Text ins Eingabefeld zurück. Abbrechen verwirft ihn.",
            "fr": "Envoyer maintenant annule le tour en cours et envoie ceci tout de suite. Modifier renvoie le texte dans le champ. Annuler le supprime.",
            "ru": "«Отправить сейчас» отменяет текущий ход и сразу отправляет это. «Изменить» возвращает текст в поле. «Отмена» отбрасывает его.",
            "es": "Enviar ahora cancela el turno actual y envía esto de inmediato. Editar lo devuelve al campo. Cancelar lo descarta.",
            "pt-BR": "Enviar agora cancela o turno atual e envia isto em seguida. Editar devolve o texto ao campo. Cancelar descarta.",
            "it": "Invia ora annulla il turno attuale e invia questo subito. Modifica riporta il testo nel campo. Annulla lo scarta.",
            "id": "Kirim sekarang membatalkan giliran saat ini dan langsung mengirim ini. Edit mengembalikan teks ke kolom. Batal membuangnya.",
            "ta": "இப்போது அனுப்பு தற்போதைய சுற்றை ரத்து செய்து இதை உடனே அனுப்பும். திருத்து உரையை உள்ளீட்டுப் பெட்டிக்குத் திருப்பும். ரத்து அதை நீக்கும்.",
            "uk": "«Надіслати зараз» скасовує поточний хід і одразу надсилає це. «Змінити» повертає текст у поле. «Скасувати» відкидає його.",
