        "Live uses each saved bridge. Personal WeChat stays paste-only. Feishu checks the credential, then you still paste.": [
            "ja": "リアルタイムは保存済みのブリッジを使います。個人 WeChat は貼り付けのみです。Feishu は資格情報を確認したあと、メッセージは貼り付けます。",
            "ko": "실시간은 저장된 브리지를 사용합니다. 개인 WeChat은 붙여넣기만 됩니다. Feishu는 자격 증명을 확인한 뒤에도 붙여넣습니다.",
            "de": "Live nutzt jede gespeicherte Brücke. Persönliches WeChat bleibt Einfügen. Feishu prüft die Zugangsdaten, danach fügst du weiter ein.",
            "fr": "Le direct utilise chaque pont enregistré. WeChat personnel reste un collage. Feishu vérifie l'identifiant, puis vous collez encore.",
            "ru": "Приём использует каждый сохранённый мост. Личный WeChat только через вставку. Feishu проверяет данные, сообщение всё равно вставляется.",
            "es": "El directo usa cada puente guardado. WeChat personal sigue siendo pegar. Feishu comprueba la credencial y aun así pegas.",
            "pt-BR": "O ao vivo usa cada ponte salva. O WeChat pessoal continua só colar. O Feishu confere a credencial e você ainda cola.",
            "it": "Il live usa ogni ponte salvato. WeChat personale resta incolla. Feishu controlla le credenziali, poi incolli ancora.",
            "id": "Mode langsung memakai setiap jembatan yang disimpan. WeChat pribadi tetap tempel. Feishu memeriksa kredensial, lalu Anda tetap menempel.",
            "ta": "நேரலை சேமித்த ஒவ்வொரு பாலத்தையும் பயன்படுத்தும். தனிப்பட்ட WeChat ஒட்டுதல் மட்டும். Feishu சான்றைச் சரிபார்த்த பிறகும் ஒட்ட வேண்டும்.",
            "uk": "Наживо використовує кожен збережений міст. Особистий WeChat лишається вставкою. Feishu перевіряє дані, повідомлення все одно вставляється.",
            "fil": "Ginagamit ng live ang bawat naka-save na tulay. Ang personal na WeChat ay paste lang. Sinusuri ng Feishu ang kredensyal, tapos magpe-paste ka pa rin.",
            "tr": "Canlı, kayıtlı her köprüyü kullanır. Kişisel WeChat yalnızca yapıştırmadır. Feishu kimliği doğrular, mesajı yine yapıştırırsınız.",
